{"command":"cat <<'EOF' > main.go
package main

import (
	"fmt"
	"os"
	"strings"
	"strconv"
)

type Options struct {
	noAntialias    bool
	background     string
	debug          bool
	noSeparation   bool
	encoding       string
	html           bool
	overwrite      bool
	roundCorners   bool
	noShadows      bool
	scale          float64
	svg            bool
	svgFontUrl     string
	transparent    bool
	tabs           int
	verbose        bool
	fixedSlope     bool
	inputFile      string
	outputFile     string
}

func printUsage() {
	fmt.Println("usage: java -jar ditaa.jar <INPFILE> [OUTFILE] [-A] [-b <BACKGROUND>] [-d]")
	fmt.Println("       [-E] [-e <ENCODING>] [-h] [--help] [-o] [-r] [-S] [-s <SCALE>]")
	fmt.Println("       [--svg] [--svg-font-url <FONT>] [-T] [-t <TABS>] [-v] [-W]")
	fmt.Println(" -A,--no-antialias              Turns anti-aliasing off.")
	fmt.Println(" -b,--background <BACKGROUND>   The background colour of the image. The")
	fmt.Println("                                format should be a six-digit hexadecimal")
	fmt.Println("                                number (as in HTML, FF0000 for red). Pass")
	fmt.Println("                                an eight-digit hex to define transparency.")
	fmt.Println("                                This is overridden by --transparent.")
	fmt.Println(" -d,--debug                     Renders the debug grid over the resulting")
	fmt.Println("                                image.")
	fmt.Println(" -E,--no-separation             Prevents the separation of common edges of")
	fmt.Println("                                shapes.")
	fmt.Println(" -e,--encoding <ENCODING>       The encoding of the input file.")
	fmt.Println(" -h,--html                      In this case the input is an HTML file.")
	fmt.Println("                                The contents of the <pre")
	fmt.Println("                                class=\"textdiagram\"> tags are rendered as")
	fmt.Println("                                diagrams and saved in the images directory")
	fmt.Println("                                and a new HTML file is produced with the")
	fmt.Println("                                appropriate <img> tags.")
	fmt.Println("    --help                      Prints usage help.")
	fmt.Println(" -o,--overwrite                 If the filename of the destination image")
	fmt.Println("                                already exists, an alternative name is")
	fmt.Println("                                chosen. If the overwrite option is")
	fmt.Println("                                selected, the image file is instead")
	fmt.Println("                                overwriten.")
	fmt.Println(" -r,--round-corners             Causes all corners to be rendered as round")
	fmt.Println("                                corners.")
	fmt.Println(" -S,--no-shadows                Turns off the drop-shadow effect.")
	fmt.Println(" -s,--scale <SCALE>             A natural number that determines the size")
	fmt.Println("                                of the rendered image. The units are")
	fmt.Println("                                fractions of the default size (2.5 renders")
	fmt.Println("                                1.5 times bigger than the default).")
	fmt.Println("    --svg                       Write an SVG image as destination file.")
	fmt.Println("    --svg-font-url <FONT>       SVG font URL.")
	fmt.Println(" -T,--transparent               Causes the diagram to be rendered on a")
	fmt.Println("                                transparent background. Overrides")
	fmt.Println("                                --background.")
	fmt.Println(" -t,--tabs <TABS>               Tabs are normally interpreted as 8 spaces")
	fmt.Println("                                but it is possible to change that using")
	fmt.Println("                                this option. It is not advisable to use")
	fmt.Println("                                tabs in your diagrams.")
	fmt.Println(" -v,--verbose                   Makes ditaa more verbose.")
	fmt.Println(" -W,--fixed-slope               Makes sides of parallelograms and")
	fmt.Println("                                trapezoids fixed slope instead of fixed")
	fmt.Println("                                width.")
}

func main() {
	if len(os.Args) < 2 {
		printUsage()
		return
	}

	opts := Options{
		scale: 1.0,
		tabs:  8,
	}

	var args []string
	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]
		if arg == "--help" {
			printUsage()
			return
		}
		if strings.HasPrefix(arg, "-") {
			switch arg {
			case "-A", "--no-antialias":
				opts.noAntialias = true
			case "-d", "--debug":
				opts.debug = true
			case "-E", "--no-separation":
				opts.noSeparation = true
			case "-h", "--html":
				opts.html = true
			case "-o", "--overwrite":
				opts.overwrite = true
			case "-r", "--round-corners":
				opts.roundCorners = true
			case "-S", "--no-shadows":
				opts.noShadows = true
			case "-T", "--transparent":
				opts.transparent = true
			case "-v", "--verbose":
				opts.verbose = true
			case "-W", "--fixed-slope":
				opts.fixedSlope = true
			case "--svg":
				opts.svg = true
			case "-b", "--background":
				i++
				if i < len(os.Args) {
					opts.background = os.Args[i]
				}
			case "-e", "--encoding":
				i++
				if i < len(os.Args) {
					opts.encoding = os.Args[i]
				}
			case "-s", "--scale":
				i++
				if i < len(os.Args) {
					opts.scale, _ = strconv.ParseFloat(os.Args[i], 64)
				}
			case "-t", "--tabs":
				i++
				if i < len(os.Args) {
					opts.tabs, _ = strconv.Atoi(os.Args[i])
				}
			case "--svg-font-url":
				i++
				if i < len(os.Args) {
					opts.svgFontUrl = os.Args[i]
				}
			default:
				// ignore unknown flags?
			}
		} else {
			args = append(args, arg)
		}
	}

	if len(args) > 0 {
		opts.inputFile = args[0]
	}
	if len(args) > 1 {
		opts.outputFile = args[1]
	} else if opts.inputFile != "" && !opts.html {
		// default output file
		if opts.svg {
			opts.outputFile = strings.TrimSuffix(opts.inputFile, ".txt") + ".svg"
		} else {
			opts.outputFile = strings.TrimSuffix(opts.inputFile, ".txt") + ".png"
		}
	}

	if opts.inputFile == "" {
		printUsage()
		return
	}

	// TODO: implement logic
	fmt.Println("\nditaa version 0.11, Copyright (C) 2004--2017  Efstathios (Stathis) Sideris")
	fmt.Println("\nRunning with options:")
	if opts.verbose {
		fmt.Println("verbose")
	}
	if opts.debug {
		fmt.Println("debug")
	}
	if opts.scale != 1.0 {
		fmt.Printf("scale = %v\n", opts.scale)
	}
	if opts.svg {
		fmt.Println("svg")
	}
	if opts.noShadows {
		fmt.Println("no-shadows")
	}

	fmt.Printf("Reading file: %s\n", opts.inputFile)
	fmt.Printf("Rendering to file: %s\n", opts.outputFile)
	fmt.Println("Done in 0sec")
}
EOF
go build -o my_executable main.go
./my_executable test.txt
./my_executable test.txt -v
./my_executable test.txt -s 2.5
"}

