		"                                trapezoids fixed slope instead of fixed\n" +
		"                                width.\n")
}

func readGrid(filename string, tabSize int) ([][]rune, int, int) {
	content, err := os.ReadFile(filename)
	if err != nil {
		return nil, 0, 0
	}
	lines := strings.Split(strings.ReplaceAll(string(content), "\r\n", "\n"), "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}

	expandedLines := make([][]rune, len(lines))
	maxW := 0
	for i, line := range lines {
		var expanded []rune
		for _, r := range line {
			if r == '\t' {
				spaces := tabSize - (len(expanded) % tabSize)
				for s := 0; s < spaces; s++ {
					expanded = append(expanded, ' ')
				}
			} else {
				expanded = append(expanded, r)
			}
		}
		expandedLines[i] = expanded
		if len(expanded) > maxW {
			maxW = len(expanded)
		}
	}

	height := len(lines) + 4
	width := maxW + 4
	grid := make([][]rune, height)
	for i := range grid {
		grid[i] = make([]rune, width)
		for j := range grid[i] {
			grid[i][j] = ' '
		}
	}

	for y, line := range expandedLines {
		for x, r := range line {
			grid[y+2][x+2] = r
		}
	}
	return grid, width, height
}

