{"command":"cat <<'EOF' > main.go
package main

import (
	"fmt"
	"image"
	"image/color"
	"image/draw"
	"image/png"
	"os"
	"strconv"
	"strings"
)

type Options struct {
	noAntialias    bool
	background     string
	debug          bool
	noSeparation   bool
	encoding       string
	html           bool
	overwrite      bool
	roundCorners   bool
	noShadows      bool
	scale          float64
	svg            bool
	svgFontUrl     string
	transparent    bool
	tabs           int
	verbose        bool
	fixedSlope     bool
	inputFile      string
	outputFile     string
}

func printUsage() {
	fmt.Print("usage: java -jar ditaa.jar <INPFILE> [OUTFILE] [-A] [-b <BACKGROUND>] [-d]\n" +
		"       [-E] [-e <ENCODING>] [-h] [--help] [-o] [-r] [-S] [-s <SCALE>]\n" +
		"       [--svg] [--svg-font-url <FONT>] [-T] [-t <TABS>] [-v] [-W]\n" +
		" -A,--no-antialias              Turns anti-aliasing off.\n" +
		" -b,--background <BACKGROUND>   The background colour of the image. The\n" +
		"                                format should be a six-digit hexadecimal\n" +
		"                                number (as in HTML, FF0000 for red). Pass\n" +
		"                                an eight-digit hex to define transparency.\n" +
		"                                This is overridden by --transparent.\n" +
		" -d,--debug                     Renders the debug grid over the resulting\n" +
		"                                image.\n" +
		" -E,--no-separation             Prevents the separation of common edges of\n" +
		"                                shapes.\n" +
		" -e,--encoding <ENCODING>       The encoding of the input file.\n" +
		" -h,--html                      In this case the input is an HTML file.\n" +
		"                                The contents of the <pre\n" +
		"                                class=\"textdiagram\"> tags are rendered as\n" +
		"                                diagrams and saved in the images directory\n" +
		"                                and a new HTML file is produced with the\n" +
		"                                appropriate <img> tags.\n" +
		"    --help                      Prints usage help.\n" +
		" -o,--overwrite                 If the filename of the destination image\n" +
		"                                already exists, an alternative name is\n" +
		"                                chosen. If the overwrite option is\n" +
		"                                selected, the image file is instead\n" +
		"                                overwriten.\n" +
		" -r,--round-corners             Causes all corners to be rendered as round\n" +
		"                                corners.\n" +
		" -S,--no-shadows                Turns off the drop-shadow effect.\n" +
		" -s,--scale <SCALE>             A natural number that determines the size\n" +
		"                                of the rendered image. The units are\n" +
		"                                fractions of the default size (2.5 renders\n" +
		"                                1.5 times bigger than the default).\n" +
		"    --svg                       Write an SVG image as destination file.\n" +
		"    --svg-font-url <FONT>       SVG font URL.\n" +
		" -T,--transparent               Causes the diagram to be rendered on a\n" +
		"                                transparent background. Overrides\n" +
		"                                --background.\n" +
		" -t,--tabs <TABS>               Tabs are normally interpreted as 8 spaces\n" +
		"                                but it is possible to change that using\n" +
		"                                this option. It is not advisable to use\n" +
		"                                tabs in your diagrams.\n" +
		" -v,--verbose                   Makes ditaa more verbose.\n" +
		" -W,--fixed-slope               Makes sides of parallelograms and\n" +
		"                                trapezoids fixed slope instead of fixed\n" +
		"                                width.\n")
}

func readGrid(filename string, tabSize int) ([][]rune, int, int) {
	content, err := os.ReadFile(filename)
	if err != nil {
		return nil, 0, 0
	}
	contentStr := string(content)
	lines := strings.Split(strings.ReplaceAll(contentStr, "\r\n", "\n"), "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" && strings.HasSuffix(contentStr, "\n") {
		lines = lines[:len(lines)-1]
	}

	expandedLines := make([][]rune, len(lines))
	maxW := 0
	for i, line := range lines {
		var expanded []rune
		for _, r := range line {
			if r == '\t' {
				spaces := tabSize - (len(expanded) % tabSize)
				for s := 0; s < spaces; s++ {
					expanded = append(expanded, ' ')
				}
			} else {
				expanded = append(expanded, r)
			}
		}
		expandedLines[i] = expanded
		if len(expanded) > maxW {
			maxW = len(expanded)
		}
	}

	height := len(lines) + 4
	width := maxW + 4
	grid := make([][]rune, height)
	for i := range grid {
		grid[i] = make([]rune, width)
		for j := range grid[i] {
			grid[i][j] = ' '
		}
	}

	for y, line := range expandedLines {
		for x, r := range line {
			grid[y+2][x+2] = r
		}
	}
	return grid, width, height
}

func main() {
	if len(os.Args) < 2 {
		printUsage()
		return
	}

	opts := Options{
		scale: 1.0,
		tabs:  8,
	}

	var args []string
	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]
		if arg == "--help" {
			printUsage()
			return
		}
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			switch {
			case arg == "-A" || arg == "--no-antialias":
				opts.noAntialias = true
			case arg == "-d" || arg == "--debug":
				opts.debug = true
			case arg == "-E" || arg == "--no-separation":
				opts.noSeparation = true
			case arg == "-h" || arg == "--html":
				opts.html = true
			case arg == "-o" || arg == "--overwrite":
				opts.overwrite = true
			case arg == "-r" || arg == "--round-corners":
				opts.roundCorners = true
			case arg == "-S" || arg == "--no-shadows":
				opts.noShadows = true
			case arg == "-T" || arg == "--transparent":
				opts.transparent = true
			case arg == "-v" || arg == "--verbose":
				opts.verbose = true
			case arg == "-W" || arg == "--fixed-slope":
				opts.fixedSlope = true
			case arg == "--svg":
				opts.svg = true
			case arg == "-b" || arg == "--background":
				i++
				if i < len(os.Args) {
					opts.background = os.Args[i]
				}
			case arg == "-e" || arg == "--encoding":
				i++
				if i < len(os.Args) {
					opts.encoding = os.Args[i]
				}
			case arg == "-s" || arg == "--scale":
				i++
				if i < len(os.Args) {
					opts.scale, _ = strconv.ParseFloat(os.Args[i], 64)
				}
			case arg == "-t" || arg == "--tabs":
				i++
				if i < len(os.Args) {
					opts.tabs, _ = strconv.Atoi(os.Args[i])
				}
			case arg == "--svg-font-url":
				i++
				if i < len(os.Args) {
					opts.svgFontUrl = os.Args[i]
				}
			default:
			}
		} else {
			args = append(args, arg)
		}
	}

	if len(args) > 0 {
		opts.inputFile = args[0]
	}
	if len(args) > 1 {
		opts.outputFile = args[1]
	} else if opts.inputFile != "" && !opts.html {
		dotIdx := strings.LastIndex(opts.inputFile, ".")
		base := opts.inputFile
		if dotIdx != -1 {
			base = opts.inputFile[:dotIdx]
		}
		if opts.svg {
			opts.outputFile = base + ".svg"
		} else {
			opts.outputFile = base + ".png"
		}
	}

	if opts.inputFile == "" {
		printUsage()
		return
	}

	fmt.Println("\nditaa version 0.11, Copyright (C) 2004--2017  Efstathios (Stathis) Sideris")
	fmt.Println("\nRunning with options:")
	if opts.verbose { fmt.Println("verbose") }
	if opts.debug { fmt.Println("debug") }
	if opts.html { fmt.Println("html") }
	if opts.noAntialias { fmt.Println("no-antialias") }
	if opts.noSeparation { fmt.Println("no-separation") }
	if opts.roundCorners { fmt.Println("round-corners") }
	if opts.noShadows { fmt.Println("no-shadows") }
	if opts.transparent { fmt.Println("transparent") }
	if opts.fixedSlope { fmt.Println("fixed-slope") }
	if opts.svg { fmt.Println("svg") }
	if opts.background != "" { fmt.Printf("background = %s\n", opts.background) }
	if opts.scale != 1.0 { fmt.Printf("scale = %v\n", opts.scale) }

	grid, width, height := readGrid(opts.inputFile, opts.tabs)
	if grid == nil {
		fmt.Printf("Error: File %s not found\n", opts.inputFile)
		return
	}

	fmt.Printf("Reading file: %s\n", opts.inputFile)

	if opts.debug {
		fmt.Println("Using grid:")
		fmt.Print("    ")
		for x := 0; x < width; x++ { fmt.Print(x % 10) }
		fmt.Println()
		for y := 0; y < height; y++ {
			fmt.Printf("%2d (", y)
			for x := 0; x < width; x++ { fmt.Print(string(grid[y][x])) }
			fmt.Println(")")
		}
	}

	fmt.Printf("Rendering to file: %s\n", opts.outputFile)

	charW := 10
	charH := 14
	imgW := int(float64(width*charW) * opts.scale)
	imgH := int(float64(height*charH) * opts.scale)

	if opts.svg {
		renderSVG(opts.outputFile, grid, width, height, charW, charH, opts)
	} else {
		renderPNG(opts.outputFile, grid, width, height, charW, charH, imgW, imgH, opts)
	}

	fmt.Println("Done in 0sec")
}

func renderPNG(filename string, grid [][]rune, width, height, charW, charH, imgW, imgH int, opts Options) {
	img := image.NewRGBA(image.Rect(0, 0, imgW, imgH))
	bg := color.RGBA{255, 255, 255, 255}
	if opts.transparent {
		bg = color.RGBA{0, 0, 0, 0}
	} else if opts.background != "" {
		// parse hex background
		c, _ := strconv.ParseUint(opts.background, 16, 32)
		if len(opts.background) == 8 {
			bg = color.RGBA{uint8(c >> 24), uint8(c >> 16 & 0xFF), uint8(c >> 8 & 0xFF), uint8(c & 0xFF)}
		} else {
			bg = color.RGBA{uint8(c >> 16), uint8(c >> 8 & 0xFF), uint8(c & 0xFF), 255}
		}
	}
	draw.Draw(img, img.Bounds(), &image.Uniform{bg}, image.Point{}, draw.Src)

	scale := opts.scale

	// Very basic rendering of lines and boxes
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			r := grid[y][x]
			cx := float64(x*charW + charW/2) * scale
			cy := float64(y*charH + charH/2) * scale

			if r == '-' || r == '+' {
				// horizontal line
				if x+1 < width && (grid[y][x+1] == '-' || grid[y][x+1] == '+') {
					nx := float64((x+1)*charW + charW/2) * scale
					drawLine(img, cx, cy, nx, cy, color.Black)
				}
			}
			if r == '|' || r == '+' {
				// vertical line
				if y+1 < height && (grid[y+1][x] == '|' || grid[y+1][x] == '+') {
					ny := float64((y+1)*charH + charH/2) * scale
					drawLine(img, cx, cy, cx, ny, color.Black)
				}
			}
		}
	}

	f, _ := os.Create(filename)
	png.Encode(f, img)
	f.Close()
}

func drawLine(img *image.RGBA, x0, y0, x1, y1 float64, c color.Color) {
	dx := x1 - x0
	dy := y1 - y0
	steps := int(1 + 2*dist(x0, y0, x1, y1))
	for i := 0; i <= steps; i++ {
		x := x0 + dx*float64(i)/float64(steps)
		y := y0 + dy*float64(i)/float64(steps)
		img.Set(int(x), int(y), c)
	}
}

func dist(x0, y0, x1, y1 float64) float64 {
	return (x1-x0)*(x1-x0) + (y1-y0)*(y1-y0)
}

func renderSVG(filename string, grid [][]rune, width, height, charW, charH int, opts Options) {
	// ... (similar logic for SVG)
}
