			for y := 0; y < h; y++ {
				for x := 0; x < w; x++ {
					if grid[y][x] == '-' || grid[y][x] == '+' {
						if x+1 < w && (grid[y][x+1] == '-' || grid[y][x+1] == '+') {
							fmt.Fprintf(f, "<line x1='%d' y1='%d' x2='%d' y2='%d' stroke='black'/>\n", x*10+5, y*14+7, (x+1)*10+5, y*14+7)
						}
					}
					if grid[y][x] == '|' || grid[y][x] == '+' {
						if y+1 < h && (grid[y+1][x] == '|' || grid[y+1][x] == '+') {
							fmt.Fprintf(f, "<line x1='%d' y1='%d' x2='%d' y2='%d' stroke='black'/>\n", x*10+5, y*14+7, x*10+5, (y+1)*14+7)
						}
					}
				}
			}
			fmt.Fprintf(f, "</svg>")
			f.Close()
		} else {
			renderToPNG(opts.outputFile, grid, w, h, opts)
		}
	}
	fmt.Println("Done in 0sec")
}
