func readGridFromLines(lines []string, tabSize int) ([][]rune, int, int) {
	expandedLines := make([][]rune, len(lines))
	maxW := 0
	for i, line := range lines {
		var expanded []rune
		for _, r := range line {
			if r == '\t' {
				spaces := tabSize - (len(expanded) % tabSize)
				for s := 0; s < spaces; s++ { expanded = append(expanded, ' ') }
			} else { expanded = append(expanded, r) }
		}
		expandedLines[i] = expanded
		if len(expanded) > maxW { maxW = len(expanded) }
	}
	height, width := len(lines)+4, maxW+4
	grid := make([][]rune, height)
	for i := range grid {
		grid[i] = make([]rune, width)
		for j := range grid[i] { grid[i][j] = ' ' }
	}
	for y, line := range expandedLines {
		for x, r := range line { grid[y+2][x+2] = r }
	}
	return grid, width, height
